import java.nio.file.*;import java.util.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class MetadataOnlyVerify {
 static List<String> inner(ClassNode c){var out=new ArrayList<String>();for(var i:c.innerClasses)out.add(i.name+"|"+i.outerName+"|"+i.innerName+"|"+i.access);return out;}
 static List<String> list(List<String> x){return x==null?List.of():x;}
 static byte[] noMeta(ClassNode c){c.nestMembers=null;c.permittedSubclasses=null;c.innerClasses=new ArrayList<>();var w=new ClassWriter(0);c.accept(w);return w.toByteArray();}
 public static void main(String[]a)throws Exception{var before=OpeningDelta.read(Files.readAllBytes(Path.of(a[0])),0);var source=OpeningDelta.read(Files.readAllBytes(Path.of(a[1])),0);var after=OpeningDelta.read(Files.readAllBytes(Path.of(a[2])),0);if(!before.name.equals(after.name)||!source.name.equals(after.name))throw new IllegalStateException("type mismatch");if(!list(after.nestMembers).containsAll(list(before.nestMembers))||!list(after.nestMembers).containsAll(list(source.nestMembers))||!list(after.permittedSubclasses).containsAll(list(before.permittedSubclasses))||!list(after.permittedSubclasses).containsAll(list(source.permittedSubclasses))||!inner(after).containsAll(inner(before))||!inner(after).containsAll(inner(source)))throw new IllegalStateException("metadata union missing member");String type=after.name;int fields=before.fields.size(),methods=before.methods.size();if(!Arrays.equals(noMeta(before),noMeta(after)))throw new IllegalStateException("nonmetadata class content changed");System.out.println("PASS METADATA_ONLY "+type+" fields="+fields+" methods="+methods+" unchangedOtherClassContent=true existingMetadataDeleted=0 newSourceMetadataUnion=true");}
}